    const x10 = lerp4(c(0, 1, 0), c(1, 1, 0), fx);
    const x01 = lerp4(c(0, 0, 1), c(1, 0, 1), fx);
    const x11 = lerp4(c(0, 1, 1), c(1, 1, 1), fx);
